def count_unique_three_digit_even_numbers(digits):
    values=set()
    for i,a in enumerate(digits):
        for j,b in enumerate(digits):
            for k,c in enumerate(digits):
                if len({i,j,k})==3 and a!=0 and c%2==0:values.add(100*a+10*b+c)
    return len(values)

